```python
# Access Control Simulation Script

# Importing required libraries
import getpass
import hashlib
import os

# Defining a dictionary to store user credentials
users = {
    "admin": {
        "password": "hashed_password",
        "locked": False
    },
    "user1": {
        "password": "hashed_password",
        "locked": False
    }
}

# Defining a function to hash passwords
def hash_password(password):
    return hashlib.sha256(password.encode()).hexdigest()

# Defining a function to check user credentials
def check_credentials(username, password):
    if username in users and users[username]["locked"] == False:
        hashed_password = hash_password(password)
        if hashed_password == users[username]["password"]:
            return True
    return False

# Defining a function to lock user accounts
def lock_account(username):
    users[username]["locked"] = True

# Defining a function to unlock user accounts
def unlock_account(username):
    users[username]["locked"] = False

# Defining a main function to simulate access control
def access_control():
    while True:
        print("Access Control Simulator")
        print("1. Login")
        print("2. Lock/Unlock Account")
        print("3. Exit")
        choice = input("Choose an option: ")

        if choice == "1":
            username = input("Enter your username: ")
            password = getpass.getpass("Enter your password: ")
            if check_credentials(username, password):
                print("Access granted!")
            else:
                print("Access denied! Incorrect username or password.")
        elif choice == "2":
            username = input("Enter your username: ")
            if username in users:
                action = input("Do you want to (L)ock or (U)unlock the account? ")
                if action.upper() == "L":
                    lock_account(username)
                    print("Account locked.")
                elif action.upper() == "U":
                    unlock_account(username)
                    print("Account unlocked.")
                else:
                    print("Invalid choice. Please try again.")
            else:
                print("User does not exist.")
        elif choice == "3":
            print("Exiting access control simulator.")
            break
        else:
            print("Invalid choice. Please try again.")

# Running the access control simulator
access_control()
```

Disclaimer: This script is for educational purposes only and should not be used in production environments. It simulates a basic access control system and is not intended to demonstrate real-world security measures. It is essential to note that actual access control systems should be implemented using secure practices and follow industry standards to prevent vulnerabilities and ensure data protection.

